#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329 # library: "$e[" is no array; unused helpers; gate checks are called indirectly
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Wisp host wizard: brings a new server to the production baseline and moves production onto it.
# The procedure, the gate and what each part proves are in docs/new-host.md.
#
#   ops/wizard.sh setup      on the new server, as its admin user, from a checkout of main
#   ops/wizard.sh env        on the server: fills /etc/wisp/production.env, secrets by hidden input
#   ops/wizard.sh gate       on the laptop: the move gate checks
#   ops/wizard.sh rehearse   on the laptop: the whole move, then puts the server back as it was
#   ops/wizard.sh move       on the laptop: move night
#   ops/wizard.sh reset      on the laptop: finishes a rehearsal that stopped before its reset
#
# Root commands are shown exactly and run only when the owner says yes. Nothing here prints a secret,
# writes a log or prints a row of data: the per-table check prints table names only (ops/table-check.sh).

REPO=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)

APP_ORIGIN=https://app.wispmoney.com
BARE_ORIGIN=https://wispmoney.com
CALLBACK_PATH=/bank-connections/callback
MCP_URL=$APP_ORIGIN/api/mcp

# The server: wisp names (ops/README.md, Production).
SERVER_ENV=/etc/wisp/production.env
SERVER_BACKUP_ENV=/etc/wisp/backup.env
SERVER_KEY=/etc/wisp/enable-banking-private.key
SERVER_DEPLOYED=/var/lib/wisp-deploy/deployed.env
SERVER_PG=wisp-production-postgres-1
SERVER_REDIS=wisp-production-redis-1
SERVER_API=wisp-production-api-1
SERVER_WEB=wisp-production-web-1
# Stopped while the database is replaced; only those running before start again.
SERVER_TIMERS=(wisp-deploy-production.timer wisp-backup.timer wisp-restore-drill.timer wisp-staging-copy.timer)
# Rehearsal snapshots and the copied dump, in the admin user's home on the server.
SERVER_WORK=wisp-move
API_UID=10001

# The laptop keeps its installed tempo names until it is switched off.
LAPTOP_ENV=/etc/tempo/production.env
LAPTOP_DEPLOYED=/var/lib/tempo-deploy/deployed.env
LAPTOP_TIMER=tempo-deploy-production.timer
LAPTOP_DEPLOY_SERVICE=tempo-deploy-production.service
LAPTOP_PG=tempo-api-production-postgres-1
LAPTOP_API=tempo-api-production-api-1
LAPTOP_WEB=tempo-api-production-web-1

# Move settings (server address, checkout) and the night's working files, on the laptop.
STATE=${XDG_STATE_HOME:-$HOME/.local/state}/wisp-move
WORK=$STATE/work

# shellcheck disable=SC2016 # runs in another shell, on either host
HEALTH_WAIT='for _ in $(seq 60); do curl -fsS -o /dev/null http://127.0.0.1:8080/api/health && exit 0; sleep 5; done; exit 1'

# ── Helpers ───────────────────────────────────────────────────────────────

show_cmd() {
  printf '    %s$' "$BOLD"
  printf ' %q' "$@"
  printf '%s\n' "$RESET"
}

# root CMD...: shows the exact root command and runs it with sudo once the owner says yes.
root() {
  show_cmd sudo "$@"
  if confirm "Run this root command now?"; then
    sudo "$@"
  else
    pause "Run it yourself in another terminal, then press Enter"
  fi
}

# root_write PATH CONTENT: shows a root-owned file's content, then writes it once the owner says yes.
root_write() {
  local path=$1 content=$2
  say "Content of $path:"
  printf '%s\n' "$content" | sed 's/^/      /'
  show_cmd sudo tee "$path"
  if confirm "Write it as root now?"; then
    printf '%s\n' "$content" | sudo tee -- "$path" >/dev/null
  else
    pause "Write it yourself in another terminal, then press Enter"
  fi
}

# remote 'COMMAND': runs a shell command on the server as the admin user.
# shellcheck disable=SC2029 # built here on purpose: fixed names only
remote() { ssh "$SERVER_SSH" "$1"; }

# remote_root CMD...: shows a root command for the server and runs it there, with a terminal for sudo.
remote_root() {
  local cmd
  cmd=$(printf '%q ' "$@")
  say "On the server:"
  show_cmd sudo "$@"
  if confirm "Run this root command on the server now?"; then
    ssh -t "$SERVER_SSH" "sudo $cmd"
  else
    pause "Run it yourself on the server (ssh $SERVER_SSH), then press Enter"
  fi
}

fail_stop() {
  warn "$1"
  exit 1
}

# ask_bool KEY "Prompt": like ask, for true or false.
ask_bool() {
  while :; do
    ask "$1" "$2 (true/false):"
    [[ ${!1} == true || ${!1} == false ]] && return
    warn "type true or false"
  done
}

# default_env KEY VALUE: writes VALUE only when ENV_FILE has no KEY yet, so the owner's own value stays.
default_env() {
  [[ -n $(_existing "$1" || true) ]] || write_env "$1" "$2"
}

random_secret() { od -An -tx1 -N32 /dev/urandom | tr -d ' \n'; }

# Settings for the laptop-side modes, kept in $STATE/settings.env (mode 600).
load_move_settings() {
  mkdir -p "$WORK"
  chmod 700 "$STATE" "$WORK"
  ENV_FILE=$STATE/settings.env
  ask SERVER_SSH "The server's SSH address on the tailnet (such as admin@wisp.example.ts.net):"
  [[ -n $SERVER_SSH ]] || fail_stop "no server address"
  write_env SERVER_SSH "$SERVER_SSH"
  ask SERVER_CHECKOUT "The Tempo checkout on the server, relative to the admin user's home (such as tempo):"
  SERVER_CHECKOUT=${SERVER_CHECKOUT#\~/}
  [[ $SERVER_CHECKOUT =~ ^[A-Za-z0-9._/-]+$ ]] || fail_stop "use a plain path such as tempo"
  write_env SERVER_CHECKOUT "$SERVER_CHECKOUT"
  remote true || fail_stop "cannot reach $SERVER_SSH over SSH"
}

# env_report FILE: one line per checked setting of an env file, never a secret: secrets as a
# sha256 or as set/unset. Runs on either host; the server's runs there over SSH.
HASHED_KEYS=(BANKING_SESSION_ENCRYPTION_KEY_B64 ENABLE_BANKING_APPLICATION_ID)
PLAIN_KEYS=(WEB_BASE_URL ENABLE_BANKING_REDIRECT_URL ENABLE_BANKING_PRIVATE_KEY_HOST_PATH
  SESSION_REDIS_KEY EMAIL_VERIFICATION_REDIS_KEY PASSWORD_RESET_REDIS_KEY)
SET_KEYS=(EMAIL_USERNAME EMAIL_PASSWORD EMAIL_FROM OPERATOR_ALERT_EMAIL)
env_report() {
  local key value
  ENV_FILE=$1
  for key in "${HASHED_KEYS[@]}"; do
    value=$(_existing "$key" || true)
    if [[ -n $value ]]; then
      printf '%s=sha256:%s\n' "$key" "$(printf '%s' "$value" | sha256sum | cut -c1-64)"
    else
      printf '%s=unset\n' "$key"
    fi
  done
  for key in "${PLAIN_KEYS[@]}"; do
    printf '%s=plain:%s\n' "$key" "$(_existing "$key" || true)"
  done
  for key in "${SET_KEYS[@]}"; do
    if [[ -n $(_existing "$key" || true) ]]; then printf '%s=set\n' "$key"; else printf '%s=unset\n' "$key"; fi
  done
}
env_report_script() {
  declare -f _existing env_report
  declare -p HASHED_KEYS PLAIN_KEYS SET_KEYS
  printf 'env_report %q\n' "$1"
}
laptop_env_report() {
  if [[ -r $LAPTOP_ENV ]]; then
    bash -c "$(env_report_script "$LAPTOP_ENV")"
  else
    note "$LAPTOP_ENV is readable by root only; sudo reads it and prints hashes, never values of secrets."
    sudo bash -c "$(env_report_script "$LAPTOP_ENV")"
  fi
}
server_env_report() { ssh "$SERVER_SSH" bash -s <<<"$(env_report_script "$SERVER_ENV")"; }
report_value() { sed -n "s/^$2=//p" <<<"$1"; }

# Compares the server's env file with the laptop's: data-bound secrets equal (by hash), the wisp
# address, Redis prefixes and email settings in place. Prints only what is wrong, by setting name.
env_matches() {
  local laptop server key problems=0 laptop_redirect path
  laptop=$(laptop_env_report) || fail_stop "could not read $LAPTOP_ENV"
  server=$(server_env_report) || fail_stop "could not read $SERVER_ENV on the server"
  for key in "${HASHED_KEYS[@]}"; do
    if [[ $(report_value "$laptop" "$key") == unset || $(report_value "$laptop" "$key") != "$(report_value "$server" "$key")" ]]; then
      warn "$key on the server is not the laptop's"
      problems=$((problems + 1))
    fi
  done
  [[ $(report_value "$server" WEB_BASE_URL) == "plain:$APP_ORIGIN" ]] || { warn "WEB_BASE_URL is not $APP_ORIGIN"; problems=$((problems + 1)); }
  laptop_redirect=$(report_value "$laptop" ENABLE_BANKING_REDIRECT_URL)
  path=/${laptop_redirect#plain:*://*/}
  [[ $path != / ]] || path=$CALLBACK_PATH
  [[ $(report_value "$server" ENABLE_BANKING_REDIRECT_URL) == "plain:$APP_ORIGIN$path" ]] ||
    { warn "ENABLE_BANKING_REDIRECT_URL is not $APP_ORIGIN$path"; problems=$((problems + 1)); }
  [[ $(report_value "$server" ENABLE_BANKING_PRIVATE_KEY_HOST_PATH) == "plain:$SERVER_KEY" ]] ||
    { warn "ENABLE_BANKING_PRIVATE_KEY_HOST_PATH is not $SERVER_KEY"; problems=$((problems + 1)); }
  for key in SESSION_REDIS_KEY EMAIL_VERIFICATION_REDIS_KEY PASSWORD_RESET_REDIS_KEY; do
    [[ $(report_value "$server" "$key") == plain:wisp-* ]] || { warn "$key has no wisp- value"; problems=$((problems + 1)); }
  done
  for key in "${SET_KEYS[@]}"; do
    [[ $(report_value "$server" "$key") == set ]] || { warn "$key is not set"; problems=$((problems + 1)); }
  done
  ((problems == 0))
}

laptop_key_path() {
  local path
  path=$(report_value "$(laptop_env_report)" ENABLE_BANKING_PRIVATE_KEY_HOST_PATH)
  printf '%s' "${path#plain:}"
}

# The banking key: the same file on both hosts, owned as "Container privileges" in ops/README.md says.
key_matches() {
  local laptop_path laptop_hash server_state user
  laptop_path=$(laptop_key_path)
  [[ -r $laptop_path ]] || fail_stop "cannot read the laptop's banking key at $laptop_path"
  laptop_hash=$(sha256sum <"$laptop_path" | cut -c1-64)
  user=$(remote 'id -un')
  server_state=$(remote "sha256sum <$SERVER_KEY | cut -c1-64; stat -c '%U %g %a' $SERVER_KEY" 2>/dev/null || true)
  [[ $server_state == "$laptop_hash"$'\n'"$user $API_UID 440" ]]
}

# Waits until a oneshot service on this host (or the server) is not running.
wait_inactive() {
  local unit=$1
  while systemctl is-active --quiet "$unit"; do note "waiting for $unit to finish"; sleep 5; done
}
wait_inactive_remote() {
  remote "while systemctl is-active --quiet $1; do sleep 5; done"
}

deployed_api() { sed -n 's/^TEMPO_API_IMAGE=//p' "$1"; }

# ── Move gate ─────────────────────────────────────────────────────────────

GATE_FAILED=()
check() {
  local name=$1
  shift
  if "$@"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗ %s%s\n' "$YELLOW" "$name" "$RESET"
    GATE_FAILED+=("$name")
  fi
}
https_ok() {
  local headers
  headers=$(curl -fsS -o /dev/null -D - --max-time 15 "$APP_ORIGIN/api/health") &&
    grep -qi '^strict-transport-security:' <<<"$headers"
}
bare_ok() {
  [[ $(curl -sS -o /dev/null --max-time 15 -w '%{http_code} %{redirect_url}' "$BARE_ORIGIN/gate-check") == "302 $APP_ORIGIN/gate-check" ]]
}
public_ports_closed() {
  local ip port open=0
  ip=$(getent ahostsv4 "${APP_ORIGIN#https://}" | awk 'NR == 1 { print $1 }')
  [[ -n $ip ]] || return 1
  for port in 22 3000 5432 6379 8080; do
    if timeout 5 bash -c ">/dev/tcp/$ip/$port" 2>/dev/null; then
      warn "port $port answers on the public address"
      open=1
    fi
  done
  ((open == 0))
}
# Reads `ss -Htln` lines on stdin: true when something listens and only on Tailscale's ranges
# (100.64.0.0/10, fd7a:115c:a1e0::/48).
tailnet_only() {
  local addresses
  addresses=$(awk '{ print $4 }')
  [[ -n $addresses ]] &&
    ! grep -vqE '^(100\.(6[4-9]|[7-9][0-9]|1[01][0-9]|12[0-7])\.[0-9.]+|\[fd7a:115c:a1e0:[0-9a-f:]*\]):22$' <<<"$addresses"
}
ssh_tailnet_only() { remote "ss -Htln 'sport = :22'" | tailnet_only; }
recent_backup() {
  local age
  age=$(remote "set -a; . $SERVER_BACKUP_ENV; set +a; restic snapshots --no-lock --host wisp-production --tag wisp-db --latest 1 --json |
    python3 -c 'import datetime, json, re, sys; s = json.load(sys.stdin); t = datetime.datetime.fromisoformat(re.sub(r\"\\.[0-9]+\", \"\", s[-1][\"time\"])); print(int((datetime.datetime.now(datetime.timezone.utc) - t).total_seconds()))'") || return 1
  [[ $age =~ ^[0-9]+$ ]] && ((age < 7 * 3600))
}
gate_checks() {
  GATE_FAILED=()
  check "HTTPS answers at $APP_ORIGIN, with HSTS" https_ok
  check "$BARE_ORIGIN forwards to the app" bare_ok
  check "no SSH, database, cache or app port answers on the public address" public_ports_closed
  check "SSH listens on tailnet addresses only" ssh_tailnet_only
  check "the egress firewall is loaded" remote 'systemctl is-active --quiet wisp-api-egress.service'
  check "the 6-hourly backup timer runs" remote 'systemctl is-active --quiet wisp-backup.timer'
  check "an off-site backup is less than 7 hours old" recent_backup
  check "a restore drill has passed" remote "journalctl -q -u wisp-restore-drill.service --grep 'restore drill passed' -n 1 --no-pager | grep -q ."
  note "The Hetzner firewall's rule list (inbound TCP 80 and 443 only) is checked with the read-only API token."
  ((${#GATE_FAILED[@]} == 0))
}

# ── Move steps shared by move and rehearse ────────────────────────────────

server_db_replace() {
  # $1: the dump on the server, relative to the admin user's home.
  remote "docker exec $SERVER_PG psql -U wisp -d postgres -qX -v ON_ERROR_STOP=1 -c 'drop database if exists wisp with (force)' -c 'create database wisp owner wisp' &&
    docker exec -i $SERVER_PG pg_restore --no-owner --no-privileges --exit-on-error -U wisp -d wisp <$1 &&
    docker exec $SERVER_REDIS redis-cli FLUSHALL >/dev/null"
}
server_fingerprints() {
  "$REPO/ops/table-check.sh" fingerprints ssh "$SERVER_SSH" docker exec -i "$SERVER_PG" psql -U wisp -d wisp
}
start_server_app() {
  remote "docker start $SERVER_API >/dev/null && docker start $SERVER_WEB >/dev/null && $HEALTH_WAIT" ||
    fail_stop "the server's app did not become healthy: docker logs $SERVER_API"
}
unfreeze_laptop() {
  say "The laptop's API and web start again, then its deploy timer."
  docker start "$LAPTOP_API" "$LAPTOP_WEB" >/dev/null
  root systemctl enable --now "$LAPTOP_TIMER"
}

# Puts the server back as it was before the rehearsal: its database, an empty Redis, its env file,
# its banking key, its timers. Safe to run again after an interruption.
reset_server() {
  remote "test -d $SERVER_WORK" || { note "no rehearsal state on the server: nothing to reset"; return; }
  remote "docker stop $SERVER_WEB $SERVER_API >/dev/null"
  if remote "test -f $SERVER_WORK/pre-rehearsal.dump"; then
    say "Restoring the server's own database and emptying Redis."
    server_db_replace "$SERVER_WORK/pre-rehearsal.dump" || fail_stop "the restore of the server's own database failed"
    if [[ -s $STATE/server-before.tsv ]]; then
      server_fingerprints >"$WORK/server-after.tsv"
      "$REPO/ops/table-check.sh" compare "$STATE/server-before.tsv" "$WORK/server-after.tsv" before after ||
        fail_stop "the server's database is not as it was before the rehearsal"
    fi
  else
    note "The rehearsal stopped before the server's database changed."
  fi
  remote "test ! -f $SERVER_WORK/production.env.before || cat $SERVER_WORK/production.env.before >$SERVER_ENV"
  if remote "test -f $SERVER_WORK/enable-banking-private.key.before && ! cmp -s $SERVER_WORK/enable-banking-private.key.before $SERVER_KEY"; then
    remote_root install -o "$(remote 'id -un')" -g "$API_UID" -m 0440 "$SERVER_WORK/enable-banking-private.key.before" "$SERVER_KEY"
  fi
  start_server_app
  if [[ -s $STATE/server-timers ]]; then
    # shellcheck disable=SC2046 # one unit name per line
    remote_root systemctl start $(cat "$STATE/server-timers")
  fi
  remote "rm -rf -- $SERVER_WORK"
  rm -f -- "$STATE/server-before.tsv" "$STATE/server-timers"
}
reset_laptop() {
  [[ -f $STATE/laptop-frozen ]] || return 0
  unfreeze_laptop
  for _ in $(seq 60); do curl -fsS -o /dev/null http://127.0.0.1:8080/api/health && break; sleep 5; done
  curl -fsS -o /dev/null http://127.0.0.1:8080/api/health || warn "the laptop's app is not healthy yet: docker logs $LAPTOP_API"
  rm -f -- "$STATE/laptop-frozen"
}

# ── Server setup ──────────────────────────────────────────────────────────

setup_wizard() {
TOTAL_STAGES=15
banner "Wisp server setup"

stage "Check the server"
# shellcheck disable=SC1091
. /etc/os-release
[[ ${VERSION_ID:-} == 26.04 && $(uname -m) == x86_64 ]] || fail_stop "this is for Ubuntu 26.04 LTS on amd64; found ${PRETTY_NAME:-unknown} on $(uname -m)"
[[ $EUID != 0 ]] || fail_stop "run this as the admin user (with sudo rights), not root; see docs/new-host.md"
id -nG | grep -qw sudo || fail_stop "$USER is not in the sudo group"
git -C "$REPO" fetch -q origin main
if [[ -n $(git -C "$REPO" status --porcelain) || $(git -C "$REPO" rev-parse HEAD) != "$(git -C "$REPO" rev-parse origin/main)" ]]; then
  fail_stop "the checkout must be a clean origin/main: git -C $REPO checkout --detach origin/main"
fi
say "Ubuntu ${VERSION_ID} on amd64, admin user $USER, checkout at origin/main."
note "Each root command is shown first and runs only when you answer y. Re-running skips finished parts."
pause

stage "Packages"
packages=(docker.io docker-compose-v2 git curl jq nftables restic python3 unattended-upgrades)
if dpkg-query -W -f '${Status}\n' "${packages[@]}" 2>/dev/null | grep -vq 'install ok installed' ||
  (($(dpkg-query -W -f '${Status}\n' "${packages[@]}" 2>/dev/null | wc -l) < ${#packages[@]})); then
  say "Docker with Compose, and the tools the install, deploy, backup and egress scripts use, from Ubuntu's archive."
  root apt-get update
  root apt-get install -y "${packages[@]}"
else
  say "Already installed: ${packages[*]}."
fi
if ! id -nG | grep -qw docker || ! id -nG | grep -qw systemd-journal; then
  say "$USER joins docker (deploys and checks) and systemd-journal (the gate reads the drill's log)."
  root usermod -aG docker,systemd-journal "$USER"
  warn "Log out and back in so the groups apply, then run ops/wizard.sh setup again."
  exit 0
fi
pause

stage "Automatic security updates"
say "Security updates install daily; one that needs a reboot reboots at 04:00 server time,"
say "clear of the 02:23 UTC release and the 00:30 and 06:30 backups."
note "Server time zone: $(timedatectl show -p Timezone --value 2>/dev/null || echo unknown)"
if [[ -f /etc/apt/apt.conf.d/52wisp-unattended-upgrades ]]; then
  say "Already configured."
else
  root_write /etc/apt/apt.conf.d/20auto-upgrades 'APT::Periodic::Update-Package-Lists "1";
APT::Periodic::Unattended-Upgrade "1";'
  root_write /etc/apt/apt.conf.d/52wisp-unattended-upgrades '// Wisp production: reboot for updates that need it, at night (docs/new-host.md).
Unattended-Upgrade::Automatic-Reboot "true";
Unattended-Upgrade::Automatic-Reboot-WithUsers "true";
Unattended-Upgrade::Automatic-Reboot-Time "04:00";'
fi
pause

stage "Tailscale"
if ! command -v tailscale >/dev/null; then
  say "Tailscale's own package repository for Ubuntu ${VERSION_CODENAME}."
  tmp=$(mktemp -d)
  curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/${VERSION_CODENAME}.noarmor.gpg" -o "$tmp/tailscale.gpg"
  curl -fsSL "https://pkgs.tailscale.com/stable/ubuntu/${VERSION_CODENAME}.tailscale-keyring.list" -o "$tmp/tailscale.list"
  note "$(cat "$tmp/tailscale.list")"
  root install -m 644 "$tmp/tailscale.gpg" /usr/share/keyrings/tailscale-archive-keyring.gpg
  root install -m 644 "$tmp/tailscale.list" /etc/apt/sources.list.d/tailscale.list
  rm -rf -- "$tmp"
  root apt-get update
  root apt-get install -y tailscale
fi
if ! tailscale ip -4 >/dev/null 2>&1; then
  say "Log the server in to your tailnet: open the address tailscale prints."
  root tailscale up
fi
root tailscale set --auto-update
open_url "https://login.tailscale.com/admin/machines"
step "In the admin console: this server → ⋯ → Disable key expiry, so it stays on the tailnet."
pause "Done?"

stage "SSH on the tailnet only"
ts4=$(tailscale ip -4)
ts6=$(tailscale ip -6 2>/dev/null || true)
ts_name=$(tailscale status --json | jq -r '.Self.DNSName | rtrimstr(".")')
if ss -Htln 'sport = :22' | tailnet_only; then
  say "sshd already listens on tailnet addresses only."
else
say "sshd listens on $ts4${ts6:+ and $ts6} only, keys only, no root login."
root_write /etc/sysctl.d/60-wisp-ssh-tailnet.conf '# sshd binds the tailnet addresses before tailscale0 is up at boot (docs/new-host.md).
net.ipv4.ip_nonlocal_bind = 1
net.ipv6.ip_nonlocal_bind = 1'
root sysctl -q --system
root_write /etc/ssh/sshd_config.d/10-wisp-tailnet.conf "# SSH on the tailnet only; the Hetzner web console is the fallback (docs/new-host.md).
ListenAddress $ts4${ts6:+
ListenAddress $ts6}
PasswordAuthentication no
KbdInteractiveAuthentication no
PermitRootLogin no"
root sshd -t
if systemctl list-unit-files ssh.socket >/dev/null 2>&1 && systemctl is-enabled --quiet ssh.socket; then
  say "Ubuntu starts sshd from a socket by default; sshd binds its own addresses instead."
  root systemctl disable --now ssh.socket
  root rm -f /etc/systemd/system/ssh.service.d/00-socket.conf /etc/systemd/system/ssh.socket.d/addresses.conf
  root systemctl daemon-reload
  root systemctl enable ssh.service
fi
root systemctl restart ssh.service
say "sshd now listens on:"
ss -Htln 'sport = :22' | awk '{ print "      " $4 }'
warn "Keep this session open. From the laptop, in a new terminal: ssh $USER@$ts_name"
pause "Press Enter once that login works"
fi

stage "Hetzner firewall"
say "Apply with the write token (owner only). Inbound, nothing else:"
step "TCP 80 from 0.0.0.0/0 and ::/0 (HTTP, redirects to HTTPS and certificate checks)"
step "TCP 443 from 0.0.0.0/0 and ::/0 (HTTPS)"
step "No other inbound rule: remove any rule for port 22 now that SSH works over the tailnet."
step "No outbound rules (everything outbound allowed); apply the firewall to this server."
note "Console: Hetzner Console → the project → Firewalls → Create Firewall. With the hcloud CLI:"
note "  hcloud firewall create --name wisp-web"
note "  hcloud firewall add-rule wisp-web --direction in --protocol tcp --port 80 --source-ips 0.0.0.0/0 --source-ips ::/0"
note "  hcloud firewall add-rule wisp-web --direction in --protocol tcp --port 443 --source-ips 0.0.0.0/0 --source-ips ::/0"
note "  hcloud firewall apply-to-resource wisp-web --type server --server <server name>"
open_url "https://console.hetzner.com/"
pause "Applied?"

stage "DNS records"
ip4=$(ip -4 -o route get 1.1.1.1 | sed -n 's/.* src \([0-9.]*\).*/\1/p')
ip6=$(ip -6 -o route get 2606:4700:4700::1111 2>/dev/null | sed -n 's/.* src \([0-9a-f:]*\).*/\1/p' || true)
say "In Hetzner DNS, zone wispmoney.com (OVH's nameservers for the domain point at the ones Hetzner lists):"
step "app   A     $ip4"
[[ -z $ip6 ]] || step "app   AAAA  $ip6"
step "@     A     $ip4"
[[ -z $ip6 ]] || step "@     AAAA  $ip6"
step "@     TXT   the SPF record Scaleway shows (v=spf1 include:… for Scaleway)"
step "the DKIM TXT record Scaleway shows (name …._domainkey), value exactly as shown"
open_url "https://console.scaleway.com/transactional-email/domains"
note "Scaleway: Transactional Email → Domains → wispmoney.com lists the SPF and DKIM records to copy."
pause "Added? Press Enter to check the app's A record"
resolved=$(getent ahostsv4 app.wispmoney.com | awk 'NR == 1 { print $1 }' || true)
if [[ $resolved == "$ip4" ]]; then say "app.wispmoney.com resolves to this server."; else warn "app.wispmoney.com resolves to '${resolved:-nothing}' so far; Caddy retries until it points here."; fi
pause

stage "Directories"
say "The env files belong to $USER (mode 600): the deploy, backup and failure-email units run as $USER."
root install -d -m 755 /etc/wisp
[[ -e $SERVER_ENV ]] || root install -m 600 -o "$USER" -g "$USER" /dev/null "$SERVER_ENV"
[[ -e $SERVER_BACKUP_ENV ]] || root install -m 600 -o "$USER" -g "$USER" /dev/null "$SERVER_BACKUP_ENV"
[[ -d /var/lib/wisp-deploy ]] || root install -d -m 755 -o "$USER" -g "$USER" /var/lib/wisp-deploy
pause

stage "The production env file"
say "The env file part runs now; ops/wizard.sh env runs it again on its own."
pause
bash "$REPO/ops/wizard.sh" env

stage "The banking key"
if [[ -f $SERVER_KEY && $(stat -c '%U %g %a' "$SERVER_KEY") == "$USER $API_UID 440" ]]; then
  say "Already installed at $SERVER_KEY."
else
  say "Copy the Enable Banking private key from the laptop (its ENABLE_BANKING_PRIVATE_KEY_HOST_PATH):"
  step "On the laptop: scp <key file> $USER@$ts_name:enable-banking-private.key"
  pause "Copied?"
  [[ -f $HOME/enable-banking-private.key ]] || fail_stop "no ~/enable-banking-private.key"
  say "It belongs to $USER and group $API_UID (the API's uid), mode 0440."
  root install -o "$USER" -g "$API_UID" -m 0440 "$HOME/enable-banking-private.key" "$SERVER_KEY"
  rm -f -- "$HOME/enable-banking-private.key"
fi
pause

stage "Off-site backups"
ENV_FILE=$SERVER_BACKUP_ENV
if [[ -z $(_existing RESTIC_REPOSITORY || true) ]]; then
  open_url "https://console.hetzner.com/"
  step "Storage Boxes → the Helsinki box: note its user (u + digits); turn on SSH support and automatic snapshots."
  ask STORAGE_BOX_USER "Storage Box user (such as u000000):"
  [[ $STORAGE_BOX_USER =~ ^u[0-9]+$ ]] || fail_stop "a Storage Box user looks like u000000"
  write_env RESTIC_REPOSITORY "sftp:$STORAGE_BOX_USER.your-storagebox.de:wisp"
fi
box=$(_existing RESTIC_REPOSITORY)
box=${box#sftp:}
box=${box%%:*}
[[ -f $HOME/.ssh/wisp-backup ]] || ssh-keygen -q -t ed25519 -f "$HOME/.ssh/wisp-backup" -N ''
if ! grep -qx "Host $box" "$HOME/.ssh/config" 2>/dev/null; then
  printf 'Host %s\n    User %s\n    Port 23\n    IdentityFile ~/.ssh/wisp-backup\n' "$box" "${box%%.*}" >>"$HOME/.ssh/config"
fi
if ! ssh -o BatchMode=yes -o ConnectTimeout=15 "$box" pwd >/dev/null 2>&1; then
  say "ssh asks for the Storage Box password once, to install the backup key:"
  ssh "$box" install-ssh-key <"$HOME/.ssh/wisp-backup.pub"
fi
if [[ -z $(_existing RESTIC_PASSWORD || true) ]]; then
  say "The restic password encrypts every backup. Keep a copy off the server: without it no backup restores."
  while :; do
    ask_secret RESTIC_PASSWORD "restic password (letters and digits, at least 24):"
    ask_secret RESTIC_PASSWORD_AGAIN "The same again:"
    [[ $RESTIC_PASSWORD =~ ^[A-Za-z0-9]{24,}$ ]] || { warn "use at least 24 letters and digits"; continue; }
    [[ $RESTIC_PASSWORD == "$RESTIC_PASSWORD_AGAIN" ]] && break
    warn "the two entries differ"
  done
  write_env RESTIC_PASSWORD "$RESTIC_PASSWORD"
  unset RESTIC_PASSWORD RESTIC_PASSWORD_AGAIN
fi
(
  set -a
  # shellcheck disable=SC1090
  . "$SERVER_BACKUP_ENV"
  set +a
  restic cat config >/dev/null 2>&1 || restic init
) || fail_stop "restic cannot open or create the repository"
ENV_FILE=$SERVER_ENV
pause

stage "Install the production units"
say "Deploy (:release), pin sync, Caddy's config, backups, the drill, the failure hook and the egress firewall."
root "$REPO/ops/install.sh" production
pause

stage "First deploy"
docker manifest inspect ghcr.io/tempo-co/api:release >/dev/null 2>&1 ||
  fail_stop "no :release image yet: run the Release workflow once (gh workflow run release.yml --ref main), then run setup again"
root systemctl enable --now wisp-deploy-production.timer
say "The first deploy pulls the images and starts the stack (a few minutes):"
root systemctl start wisp-deploy-production.service
if bash -c "$HEALTH_WAIT"; then say "The app answers on the server."; else fail_stop "the app is not healthy: journalctl -u wisp-deploy-production.service -n 50"; fi
if curl -fsS -o /dev/null --max-time 15 "$APP_ORIGIN/api/health"; then say "And at $APP_ORIGIN."; else warn "$APP_ORIGIN does not answer yet (DNS or certificates); the gate checks it again."; fi
pause

stage "Egress firewall"
say "Loads now and at every boot; it needs the stack's networks, which the first deploy created."
root systemctl enable --now wisp-api-egress.service
if systemctl is-active --quiet wisp-api-egress.service; then say "Loaded."; else warn "not active: journalctl -u wisp-api-egress.service"; fi
pause

stage "Backups, the drill and failure emails"
root systemctl enable --now wisp-backup.timer wisp-restore-drill.timer
say "One backup and one test restore now, for the move gate:"
root systemctl start wisp-backup.service
root systemctl start wisp-restore-drill.service
say "A test failure email to OPERATOR_ALERT_EMAIL, subject '[wisp] wizard-test failed on …':"
root systemctl start wisp-failure-email@wizard-test.service
pause "Arrived?"

stage "Next"
say "The server is at the production baseline, with an empty database."
step "From the laptop: ops/wizard.sh gate (the move gate), then ops/wizard.sh rehearse, then move night."
note "Staging's feed (docs/staging-feed.md, Setting it up) needs the owner's account id, so it follows the move."
pause
finish
}

# ── The production env file ───────────────────────────────────────────────

env_wizard() {
TOTAL_STAGES=7
ENV_FILE=$SERVER_ENV
banner "Wisp production env file"

stage "Fixed settings"
[[ -w $ENV_FILE ]] || fail_stop "$ENV_FILE must exist and belong to $USER (setup's Directories stage creates it)"
say "Wisp names and the public address."
write_env NODE_ENV production
write_env PORT 3000
write_env API_URL http://api:3000
write_env DB_USERNAME wisp
write_env DB_NAME wisp
write_env DB_SYNCHRONIZE false
write_env SESSION_REDIS_KEY wisp-session
write_env EMAIL_VERIFICATION_REDIS_KEY wisp-email-verification
write_env PASSWORD_RESET_REDIS_KEY wisp-password-reset
write_env WEB_BASE_URL "$APP_ORIGIN"
write_env ENABLE_BANKING_API_URL https://api.enablebanking.com
write_env ENABLE_BANKING_REDIRECT_URL "$APP_ORIGIN$CALLBACK_PATH"
write_env ENABLE_BANKING_PRIVATE_KEY_HOST_PATH "$SERVER_KEY"
default_env SESSION_EXPIRATION 30d
default_env EMAIL_VERIFICATION_EXPIRATION 24h
default_env PASSWORD_RESET_EXPIRATION 1h
default_env THROTTLE_TTL 1m
default_env THROTTLE_LIMIT 100
pause

stage "The server's own secrets"
say "A database password and a session secret of the server's own, generated once and never shown."
note "A new session secret logs every device out: each one logs in again after the move."
if [[ -z $(_existing DB_PASSWORD || true) ]]; then write_env DB_PASSWORD "$(random_secret)"; else say "DB_PASSWORD is set (PostgreSQL keeps the first one: never change it here)."; fi
default_env SESSION_SECRET "$(random_secret)"
pause

stage "Enable Banking"
say "The same Enable Banking application as the laptop's production, so live sync carries on."
ask ENABLE_BANKING_APPLICATION_ID "Application ID (the laptop's ENABLE_BANKING_APPLICATION_ID):"
[[ -n $ENABLE_BANKING_APPLICATION_ID ]] || fail_stop "the application ID is required"
write_env ENABLE_BANKING_APPLICATION_ID "$ENABLE_BANKING_APPLICATION_ID"
say "Stored bank sessions are encrypted with the laptop's key: the server needs exactly that key."
while :; do
  ask_secret BANKING_SESSION_ENCRYPTION_KEY_B64 "BANKING_SESSION_ENCRYPTION_KEY_B64 (the laptop's):"
  (($(base64 -d <<<"$BANKING_SESSION_ENCRYPTION_KEY_B64" 2>/dev/null | wc -c) == 32)) && break
  warn "that is not base64 of 32 bytes"
done
write_env BANKING_SESSION_ENCRYPTION_KEY_B64 "$BANKING_SESSION_ENCRYPTION_KEY_B64"
unset BANKING_SESSION_ENCRYPTION_KEY_B64
pause

stage "Email through Scaleway"
say "App and alert email go through Scaleway Transactional Email (smtp.tem.scaleway.com, STARTTLS)."
open_url "https://console.scaleway.com/transactional-email/domains"
step "Transactional Email → Domains → wispmoney.com → SMTP: the user is the project ID."
ask EMAIL_USERNAME "SMTP user (the Scaleway project ID):"
write_env EMAIL_USERNAME "$EMAIL_USERNAME"
step "IAM → API keys → an API key with Transactional Email rights: its secret key is the SMTP password."
ask_secret EMAIL_PASSWORD "SMTP password (the API key's secret key):"
[[ -n $EMAIL_PASSWORD ]] || fail_stop "the SMTP password is required"
write_env EMAIL_PASSWORD "$EMAIL_PASSWORD"
unset EMAIL_PASSWORD
ask EMAIL_FROM "Sender, a wispmoney.com address (such as Wisp <hello@wispmoney.com>):"
[[ $EMAIL_FROM == *@wispmoney.com* ]] || warn "Scaleway sends only from the verified domain, wispmoney.com"
write_env EMAIL_FROM "$EMAIL_FROM"
ask OPERATOR_ALERT_EMAIL "Where failure emails go (OPERATOR_ALERT_EMAIL):"
[[ $OPERATOR_ALERT_EMAIL == ?*@?*.?* ]] || fail_stop "an email address is required"
write_env OPERATOR_ALERT_EMAIL "$OPERATOR_ALERT_EMAIL"
pause

stage "Claude categorization and features"
say "Same choices as the laptop's production env file (ops/README.md describes each)."
for flag in AI_CATEGORIZATION_ENABLED AI_CATEGORIZATION_WEB_SEARCH_ENABLED MERCHANT_LOGOS_ENABLED FILE_IMPORT_ENABLED FILE_IMPORT_MAPPER_ENABLED; do
  ask_bool "$flag" "$flag"
  write_env "$flag" "${!flag}"
done
if [[ $AI_CATEGORIZATION_ENABLED == true || $MERCHANT_LOGOS_ENABLED == true || $FILE_IMPORT_MAPPER_ENABLED == true ]]; then
  ask_secret ANTHROPIC_API_KEY "ANTHROPIC_API_KEY:"
  [[ -n $ANTHROPIC_API_KEY ]] || fail_stop "these features need ANTHROPIC_API_KEY"
  write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
  unset ANTHROPIC_API_KEY
fi
if [[ $AI_CATEGORIZATION_ENABLED == true && $AI_CATEGORIZATION_WEB_SEARCH_ENABLED == true ]]; then
  ask_secret BRAVE_SEARCH_API_KEY "BRAVE_SEARCH_API_KEY:"
  [[ -n $BRAVE_SEARCH_API_KEY ]] || fail_stop "web search needs BRAVE_SEARCH_API_KEY"
  write_env BRAVE_SEARCH_API_KEY "$BRAVE_SEARCH_API_KEY"
  unset BRAVE_SEARCH_API_KEY
fi
if [[ $MERCHANT_LOGOS_ENABLED == true ]]; then
  ask_secret LOGO_DEV_SECRET_KEY "LOGO_DEV_SECRET_KEY (Enter to go without logo.dev):"
  [[ -z $LOGO_DEV_SECRET_KEY ]] || write_env LOGO_DEV_SECRET_KEY "$LOGO_DEV_SECRET_KEY"
  unset LOGO_DEV_SECRET_KEY
fi
pause

stage "Push notifications"
if [[ -n $(_existing WEB_PUSH_VAPID_PRIVATE_KEY || true) ]]; then
  say "The server has its VAPID key pair."
else
  say "A new VAPID key pair for $APP_ORIGIN, made with the API image's web-push and never shown."
  note "Devices allowed notifications for the old address; each turns them on again after the move."
  if pair=$(docker run --rm --network none --entrypoint node ghcr.io/tempo-co/api:release \
    -e 'const k = require("web-push").generateVAPIDKeys(); console.log(k.publicKey + " " + k.privateKey)' 2>/dev/null) &&
    read -r vapid_public vapid_private <<<"$pair" && [[ -n ${vapid_private:-} ]]; then
    write_env WEB_PUSH_VAPID_PUBLIC_KEY "$vapid_public"
    write_env WEB_PUSH_VAPID_PRIVATE_KEY "$vapid_private"
  else
    warn "could not generate one here; paste a pair from npx web-push generate-vapid-keys"
    ask WEB_PUSH_VAPID_PUBLIC_KEY "Public key:"
    write_env WEB_PUSH_VAPID_PUBLIC_KEY "$WEB_PUSH_VAPID_PUBLIC_KEY"
    ask_secret WEB_PUSH_VAPID_PRIVATE_KEY "Private key:"
    write_env WEB_PUSH_VAPID_PRIVATE_KEY "$WEB_PUSH_VAPID_PRIVATE_KEY"
  fi
  unset pair vapid_public vapid_private WEB_PUSH_VAPID_PRIVATE_KEY
fi
default_env WEB_PUSH_VAPID_SUBJECT "mailto:$(_existing OPERATOR_ALERT_EMAIL)"
pause

stage "Check"
missing=()
for key in NODE_ENV PORT API_URL WEB_BASE_URL DB_USERNAME DB_PASSWORD DB_NAME DB_SYNCHRONIZE SESSION_SECRET \
  SESSION_EXPIRATION SESSION_REDIS_KEY ENABLE_BANKING_API_URL ENABLE_BANKING_APPLICATION_ID ENABLE_BANKING_REDIRECT_URL \
  ENABLE_BANKING_PRIVATE_KEY_HOST_PATH BANKING_SESSION_ENCRYPTION_KEY_B64 EMAIL_USERNAME EMAIL_PASSWORD EMAIL_FROM \
  OPERATOR_ALERT_EMAIL EMAIL_VERIFICATION_EXPIRATION EMAIL_VERIFICATION_REDIS_KEY PASSWORD_RESET_EXPIRATION \
  PASSWORD_RESET_REDIS_KEY THROTTLE_TTL THROTTLE_LIMIT; do
  [[ -n $(_existing "$key" || true) ]] || missing+=("$key")
done
((${#missing[@]} == 0)) || fail_stop "still missing: ${missing[*]}"
say "Every setting the API needs is in $ENV_FILE."
note "The API reads it when it starts: a running stack picks changes up at the next deploy or restart."
pause
finish
}

# ── Move gate ─────────────────────────────────────────────────────────────

gate_wizard() {
TOTAL_STAGES=1
stage "Move gate"
load_move_settings
if gate_checks; then
  say "The gate passes: the owner's data may move (rehearse first: ops/wizard.sh rehearse)."
else
  warn "${#GATE_FAILED[@]} check(s) fail: no data moves until they pass."
  exit 1
fi
}

# ── Move night and the rehearsal ──────────────────────────────────────────

move_wizard() {
local mode=$1 # move or rehearse
TOTAL_STAGES=16
if [[ $mode == rehearse ]]; then banner "Wisp move rehearsal"; else banner "Wisp move night"; fi

stage "Settings and the move gate"
load_move_settings
remote "test ! -e $SERVER_WORK" || fail_stop "an earlier rehearsal left ~/$SERVER_WORK on the server: run ops/wizard.sh reset first"
[[ ! -e $STATE/laptop-frozen ]] || fail_stop "an earlier rehearsal left the laptop frozen: run ops/wizard.sh reset first"
remote "test -x $SERVER_CHECKOUT/ops/wizard.sh" || fail_stop "no ops/wizard.sh in ~/$SERVER_CHECKOUT on the server"
gate_checks || fail_stop "the move gate fails; nothing has changed"
if [[ $mode == rehearse ]]; then
  say "A rehearsal runs every step of the move, then puts the server back as it was and restarts the laptop."
  note "While it runs, the server's copy makes no scheduled bank syncs and sends no bank alerts."
fi
pause

stage "Enable Banking's redirect address"
open_url "https://enablebanking.com/cp/applications"
step "Open the production application and add the redirect URL $APP_ORIGIN$CALLBACK_PATH"
step "Keep the laptop's redirect URL until the laptop is switched off; save."
pause "Saved?"

stage "The server's env file"
if [[ $mode == rehearse ]]; then
  say "Snapshots of the server's env file and banking key, for the reset."
  remote "umask 077 && mkdir $SERVER_WORK && cp $SERVER_ENV $SERVER_WORK/production.env.before && cp $SERVER_KEY $SERVER_WORK/enable-banking-private.key.before"
else
  remote "umask 077 && mkdir -p $SERVER_WORK"
fi
until env_matches; do
  say "The env file part runs on the server; type the missing values there."
  pause
  ssh -t "$SERVER_SSH" "cd $SERVER_CHECKOUT && ops/wizard.sh env" || true
  confirm "Check the env file again?" || fail_stop "stopped before any change to the laptop (ops/wizard.sh reset tidies the server)"
done
say "The server's env file has the laptop's data-bound secrets, the wisp address and Scaleway email."
if [[ $mode == rehearse ]]; then
  remote "grep -v '^BANK_CONNECTION_ALERTS_ENABLED=' $SERVER_ENV >$SERVER_WORK/env.tmp; echo BANK_CONNECTION_ALERTS_ENABLED=false >>$SERVER_WORK/env.tmp; cat $SERVER_WORK/env.tmp >$SERVER_ENV; rm $SERVER_WORK/env.tmp"
  note "Rehearsal only: BANK_CONNECTION_ALERTS_ENABLED=false until the reset."
fi
pause

stage "The banking key"
if key_matches; then
  say "The server's banking key is the laptop's, owned by its admin user and group $API_UID, mode 0440."
else
  say "Copying the laptop's banking key to the server over the tailnet."
  scp -q "$(laptop_key_path)" "$SERVER_SSH:$SERVER_WORK/enable-banking-private.key"
  remote_root install -o "$(remote 'id -un')" -g "$API_UID" -m 0440 "$SERVER_WORK/enable-banking-private.key" "$SERVER_KEY"
  remote "rm -f $SERVER_WORK/enable-banking-private.key"
  key_matches || fail_stop "the server's banking key still differs"
  say "Installed."
fi
pause

stage "Freeze the laptop"
warn "From here the laptop's app is offline until the server serves (about 30 minutes)."
confirm "Freeze the laptop's production now?" || fail_stop "stopped before the freeze"
if [[ $mode == rehearse ]]; then
  root systemctl stop "$LAPTOP_TIMER"
else
  root systemctl disable --now "$LAPTOP_TIMER"
fi
wait_inactive "$LAPTOP_DEPLOY_SERVICE"
docker stop "$LAPTOP_WEB" "$LAPTOP_API" >/dev/null
: >"$STATE/laptop-frozen"
say "The laptop's deploy timer, API and web are stopped; its database stays up for the dump."
pause

stage "The same release on both hosts"
until [[ $(deployed_api "$LAPTOP_DEPLOYED") == "$(remote "sed -n 's/^TEMPO_API_IMAGE=//p' $SERVER_DEPLOYED")" ]]; do
  warn "The server runs another API image than the laptop: the restored schema must match its code."
  step "Release now: gh workflow run release.yml --ref main, wait for it, then deploy the server:"
  remote_root systemctl start wisp-deploy-production.service
  confirm "Compare again?" || fail_stop "stopped with the laptop frozen: ops/wizard.sh reset restarts it"
done
say "Both hosts run the same API image."
pause

stage "Stop the server's app"
for timer in "${SERVER_TIMERS[@]}"; do
  if remote "systemctl is-active --quiet $timer"; then echo "$timer"; fi
done >"$STATE/server-timers"
if [[ -s $STATE/server-timers ]]; then
  # shellcheck disable=SC2046 # one unit name per line
  remote_root systemctl stop $(cat "$STATE/server-timers")
fi
for service in wisp-deploy-production wisp-backup wisp-restore-drill wisp-staging-copy; do
  wait_inactive_remote "$service.service"
done
remote "docker stop $SERVER_WEB $SERVER_API >/dev/null"
if [[ $mode == rehearse ]]; then
  server_fingerprints >"$STATE/server-before.tsv"
  remote "docker exec $SERVER_PG pg_dump --format=custom -U wisp wisp >$SERVER_WORK/pre-rehearsal.tmp && mv $SERVER_WORK/pre-rehearsal.tmp $SERVER_WORK/pre-rehearsal.dump" ||
    fail_stop "could not save the server's own database: run ops/wizard.sh reset"
  say "The server's timers, API and web are stopped; its own database is saved for the reset."
else
  remote "mkdir -p backups/wisp && docker exec $SERVER_PG pg_dump --format=custom -U wisp wisp >backups/wisp/wisp-pre-move-\$(date +%Y%m%d-%H%M%S).dump"
  say "The server's timers, API and web are stopped; its pre-move database is in ~/backups/wisp/wisp-pre-move-*.dump."
fi
pause

stage "Dump the laptop's database"
(umask 077 && docker exec "$LAPTOP_PG" pg_dump --format=custom -U tempo tempo >"$WORK/move.dump") || fail_stop "pg_dump failed"
docker exec -i "$LAPTOP_PG" pg_restore --list <"$WORK/move.dump" >/dev/null || fail_stop "the dump does not read back"
say "Dumped and validated: $(du -h "$WORK/move.dump" | cut -f1)."
pause

stage "Copy over the tailnet"
scp -q "$WORK/move.dump" "$SERVER_SSH:$SERVER_WORK/move.dump"
[[ $(sha256sum <"$WORK/move.dump" | cut -c1-64) == "$(remote "sha256sum <$SERVER_WORK/move.dump | cut -c1-64")" ]] ||
  fail_stop "the copy on the server differs from the dump"
say "Copied; the server's copy has the same checksum."
pause

stage "Restore on the server"
server_db_replace "$SERVER_WORK/move.dump" || fail_stop "the restore failed; the server's app stays stopped"
remote "rm -f $SERVER_WORK/move.dump"
say "Restored into a fresh wisp database; Redis is empty, so every device logs in again."
pause

stage "Per-table check"
"$REPO/ops/table-check.sh" fingerprints docker exec -i "$LAPTOP_PG" psql -U tempo -d tempo >"$WORK/laptop.tsv"
server_fingerprints >"$WORK/server.tsv"
if "$REPO/ops/table-check.sh" compare "$WORK/laptop.tsv" "$WORK/server.tsv" laptop server; then
  say "Every table has the laptop's row count and row hash."
elif [[ $mode == rehearse ]]; then
  warn "The rehearsal found differences: fix them before move night. The reset still runs."
else
  warn "The server's copy differs from the laptop's. The server's app stays stopped."
  if confirm "Go back to the laptop (start its API, web and deploy timer)?"; then
    unfreeze_laptop
    rm -f -- "$STATE/laptop-frozen"
  fi
  exit 1
fi
pause

stage "Start the server's app"
if [[ $mode == rehearse ]]; then
  remote "docker exec $SERVER_PG psql -U wisp -d wisp -qX -v ON_ERROR_STOP=1 -c 'update bank_connections set \"nextSyncAt\" = null'"
  note "Rehearsal only: the copy's bank connections have no scheduled sync."
fi
start_server_app
if curl -fsS -o /dev/null --max-time 15 "$APP_ORIGIN/api/health"; then say "$APP_ORIGIN answers."; else warn "$APP_ORIGIN does not answer from here"; fi
if [[ $mode == move ]]; then
  if [[ -s $STATE/server-timers ]]; then
    # shellcheck disable=SC2046 # one unit name per line
    remote_root systemctl start $(cat "$STATE/server-timers")
  fi
  rm -f -- "$STATE/server-timers"
  say "The first backup of the moved data runs now, in the background:"
  remote_root systemctl start --no-block wisp-backup.service
fi
pause

stage "Log in on each device"
open_url "$APP_ORIGIN"
step "On each device, open $APP_ORIGIN and log in (sessions did not move)."
step "Where the app is on a home screen, remove the old one and add $APP_ORIGIN instead."
[[ $mode == move ]] || note "Rehearsal: logging in checks the copy; the reset discards it."
pause "Done?"

stage "Notifications on again"
step "On each device that had notifications: Settings → Account → turn them on again."
note "The server has its own key pair and address, so old subscriptions don't carry over."
pause "Done?"

stage "The new MCP URL"
step "In every MCP client that used the old address, change the URL to $MCP_URL"
note "Personal access tokens moved with the data: the same token works."
pause "Done?"

if [[ $mode == rehearse ]]; then
  stage "Reset the server and the laptop"
  say "Discards the copy and puts the server back as it was before the rehearsal, then restarts the laptop."
  confirm "Reset now?" || fail_stop "stopped before the reset: run ops/wizard.sh reset"
  reset_server
  reset_laptop
  rm -rf -- "$WORK"
  say "The server is as it was before the rehearsal, and the laptop serves again."
else
  stage "The first sync and the laptop"
  rm -rf -- "$WORK"
  rm -f -- "$STATE/laptop-frozen"
  step "After the next scheduled sync (within 6 hours), check that each bank connection shows a sync after tonight."
  step "Keep the laptop's stack until the switch-off checks pass (docs/new-host.md): it is the way back."
  step "Then set up staging's feed with the owner account's id: docs/staging-feed.md, Setting it up."
  remote "rm -rf -- $SERVER_WORK"
  note "The laptop's deploy timer is disabled; its API and web stay stopped."
fi
pause
finish
}

reset_wizard() {
TOTAL_STAGES=2
stage "Settings"
load_move_settings
stage "Reset the server and the laptop"
reset_server
reset_laptop
rm -rf -- "$WORK"
say "The server is as it was before the rehearsal, and the laptop serves again."
}

run_wizard() {
case ${1:-} in
  setup) setup_wizard ;;
  env) env_wizard ;;
  gate) gate_wizard ;;
  rehearse | move) move_wizard "$1" ;;
  reset) reset_wizard ;;
  *)
    echo "usage: $0 setup | env | gate | rehearse | move | reset   (docs/new-host.md)" >&2
    exit 2
    ;;
esac
}

run_wizard "$@"; exit
